-- ======================
-- Grupos y Mouse (Interacción)
-- ======================
-- Groups
-- bind = $mainMod, g, togglegroup
-- bind = $mainMod, Tab, changegroupactive
-- bind = $mainMod, l, lockactivegroup, toggle

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag())
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize())
hl.bind(mainMod .. " + ALT + mouse:272", hl.dsp.window.resize())

-- ======================
-- Volume and Media / Brightness
-- ======================
-- Se ha actualizado 'bindl' a 'bindel' en el volumen para permitir mantener presionada la tecla
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd(okpanel .. " volume-up"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd(okpanel .. " volume-down"), { locked = true, repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd(okpanel .. " mute"), { locked = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })

-- Brightness
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("/home/efrain/.config/hypr/scripts/brightness/changeBrightness.sh increase"), { locked = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("/home/efrain/.config/hypr/scripts/brightness/changeBrightness.sh decrease"), { locked = true })

-- Tecla de calculadora: abre el launcher de OkPanel directo en modo "=" (cálculo).
-- Si tu tecla no dispara, ejecuta `wev` y cambia XF86Calculator por el keysym real.
hl.bind("XF86Calculator", hl.dsp.exec_cmd("ags request -i OkPanel calc"))
